('bmlt-biochemical-identification-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',1600,$json${"question":"Which enzyme is detected by the catalase test?","translation":"","options":["Catalase","Coagulase","Oxidase","Urease"],"correctIndex":0,"explanation":"Catalase breaks hydrogen peroxide into water and oxygen; bubbling indicates a positive reaction.","explanationNe":"Catalase ले hydrogen peroxide लाई पानी र oxygen मा तोड्छ; bubble देखिनु positive हो।","topic":"Biochemical Identification Tests"}$json$::jsonb,true),
